                      </div>
                      {r.assignments.length === 0 ? (
                        <div className="mt-1 text-xs text-[var(--ink-4)] italic">
                          {t.notAssigned}
                        </div>
                      ) : (
                        <div className="mt-1.5 flex flex-wrap gap-1.5">
                          {r.assignments.map((a) => (
                            <Link
                              key={`${r.id}-${a.propertyId}`}
                              href={`/dashboard?property=${a.propertyId}&view=cleaning`}
                              className="inline-flex items-center gap-1.5 rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-2 py-0.5 text-[11px] text-[var(--ink-2)] hover:bg-[var(--bg-3)]"
                            >
                              <span>{a.propertyName}</span>
                              <span className="text-[10px] uppercase tracking-wide text-[var(--ink-4)]">
                                {priorityLabel(a.priority)}
                              </span>
                            </Link>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="flex shrink-0 items-center gap-1">
                      <button
                        type="button"
                        onClick={() => startEdit(r)}
                        disabled={busy}
                        className="rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-2.5 py-1 text-xs text-[var(--ink-2)] hover:bg-[var(--bg-3)] disabled:opacity-50"
                      >
                        {t.edit}
                      </button>
                      <button
                        type="button"
                        onClick={() => remove(r.id)}
                        disabled={busy}
                        className="rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-2.5 py-1 text-xs text-rose-500 hover:bg-rose-500/10 disabled:opacity-50"
                      >
                        {t.delete}
                      </button>
                    </div>
                  </div>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useI18n } from "@/lib/i18n/context";
import { resolveCopy, type Locale, type CopyMap } from "@/lib/i18n/translations";

// RT-25.9 tick 25 — Message templates sub-route at
// /dashboard/admin/workspace/message-templates. Cross-property overview
// of every MessageTemplate the user can manage (own + managed
// properties). Same aggregation pattern as ical-links (tick 16) +
// feed-tokens (tick 18) + sync-logs (tick 17): read-only summary in the
// admin shell, edits stay on the per-property Sync settings tab via a
// deep-link. Reuses GET /api/message-templates — extended in this tick
// to accept no propertyId and return all accessible templates with
// property metadata included for grouping. No superadmin gating; data
// is the user's own. Cleaners bounce at the shell.

interface MessageTemplateRow {
  id: number;
  propertyId: number;
  name: string;
  language: string;
  subject: string;
  body: string;
  createdAt: string;
  property: { id: number; name: string };
}

interface ApiResponse {
  templates?: MessageTemplateRow[];
}

interface CopyShape {
  failedToLoad: string;
  title: string;
  subtitle: string;
  loading: string;
  empty: string;
  summary: (total: number, properties: number) => string;
  openSync: string;
}

const COPY: CopyMap<CopyShape> = {
  en: {
    failedToLoad: "Failed to load",
    title: "Message templates",
    subtitle: "All message templates across your properties. Click a property to open its Sync settings, where templates are edited.",
    loading: "Loading...",
    empty: "No templates yet. Open a property and add them on its Sync settings tab.",
    summary: (total, properties) =>
      `${total} template${total === 1 ? "" : "s"} across ${properties} propert${properties === 1 ? "y" : "ies"}.`,
    openSync: "Open Sync",
