            onClick={onClose}
            className="rounded-md p-1 text-[var(--ink-3)] hover:bg-[var(--line-2)] hover:text-[var(--ink)]"
            aria-label="Close"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="max-h-[60vh] overflow-y-auto">
          {loading ? (
            <div className="py-12 text-center text-sm text-[var(--ink-4)]">Loading…</div>
          ) : entries.length === 0 ? (
            <div className="py-12 text-center text-sm text-[var(--ink-4)]">No activity yet.</div>
          ) : (
            <ul className="space-y-1.5">
              {entries.map((e) => (
                <li
                  key={e.id}
                  className="flex items-center justify-between gap-3 rounded-md border border-[var(--line)] bg-[var(--bg)] px-3 py-2 text-xs"
                >
                  <div className="flex min-w-0 flex-1 items-center gap-2">
                    <span
                      className={
                        "shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase " +
                        (e.action === "create"
                          ? "bg-emerald-500/15 text-emerald-500"
                          : e.action === "delete"
                          ? "bg-rose-500/15 text-rose-500"
                          : "bg-sky-400/15 text-sky-400")
                      }
                    >
                      {e.action}
                    </span>
                    <span className="shrink-0 text-[var(--ink-3)]">{e.resourceType}</span>
                    <span className="truncate text-[var(--ink)]">{summarize(e)}</span>
                  </div>
                  <span className="shrink-0 text-[var(--ink-4)]">{formatDate(e.createdAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useI18n } from "@/lib/i18n/context";
import { resolveCopy, type Locale, type CopyMap } from "@/lib/i18n/translations";

interface Props {
  url: string;
}

interface CopyShape {
  copyLink: string;
  copied: string;
}

const COPY: CopyMap<CopyShape> = {
  en: { copyLink: "Copy link", copied: "Copied!" },
  ru: { copyLink: "Скопировать ссылку", copied: "Скопировано!" },
  de: { copyLink: "Link kopieren", copied: "Kopiert!" },
  fr: { copyLink: "Copier le lien", copied: "Copié !" },
  es: { copyLink: "Copiar enlace", copied: "¡Copiado!" },
};

/**
 * One-tap "Copy link" button for the share row. Falls back to a manual
 * select when navigator.clipboard is unavailable (older browsers, file://
 * previews, etc.) so the affordance never breaks silently.
 */
export function BlogCopyLink({ url }: Props) {
  const { locale } = useI18n();
  const t = resolveCopy(COPY, locale);
  const [copied, setCopied] = useState(false);

  const onClick = async () => {
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(url);
      } else {
        // Legacy fallback: select a hidden textarea, execCommand("copy").
        const ta = document.createElement("textarea");
        ta.value = url;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
      }
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Permissions blocked clipboard access — show the URL so the reader
      // can copy it manually instead of pretending we succeeded.
      window.prompt("Copy this link:", url);
    }
  };

  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex items-center gap-1.5 rounded-md border border-[var(--line)] bg-[var(--bg-2)]/40 px-2.5 py-1 text-xs font-medium text-[var(--ink-2)] transition-colors hover:border-[var(--line-2)] hover:bg-[var(--bg-2)] hover:text-[var(--ink)]"
    >
      {copied ? t.copied : t.copyLink}
    </button>
  );
}

