  cleaning: string;
  acrossAllProperties: (count: number) => string;
  allPropertiesLabel: (count: number) => string;
  view: string;
  potentialHelper: string;
  dataSources: string;
  dataSourcesHelper: string;
}

const COPY: CopyMap<CopyShape> = {
  en: {
