  },
  es: {
    emptyState: "Añada un alojamiento para ver el calendario de limpiezas.",
    cleaning: "Limpieza",
    acrossAllProperties: (count) =>
      `En todos los ${count} ${count === 1 ? "alojamiento" : "alojamientos"}`,
