interface MessageTemplate {
  id: number;
  propertyId: number;
  name: string;
  language: string;
  subject: string;
  body: string;
}

interface MessageTemplatesPanelProps {
  propertyId: number;
}

const SAMPLE_VARS: Record<string, string> = {
  guestName: "John Smith",
  checkIn: "2026-06-12",
  checkOut: "2026-06-19",
  wifiPassword: "rent-tool-12345",
  propertyName: "Sample Property",
};

const VAR_HINTS = ["{{guestName}}", "{{checkIn}}", "{{checkOut}}", "{{wifiPassword}}", "{{propertyName}}"];

function renderTemplate(input: string, vars: Record<string, string>): string {
  return input.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) =>
    Object.prototype.hasOwnProperty.call(vars, k) ? vars[k] : `{{${k}}}`
  );
}

export function MessageTemplatesPanel({ propertyId }: MessageTemplatesPanelProps) {
  const { locale } = useI18n();
  const c = resolveCopy(COPY, locale);
  const [templates, setTemplates] = useState<MessageTemplate[]>([]);
  const [editingId, setEditingId] = useState<number | "new" | null>(null);
  const [name, setName] = useState("");
  const [language, setLanguage] = useState("en");
  const [subject, setSubject] = useState("");
  const [bodyText, setBodyText] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const refresh = async () => {
    const res = await fetch(`/api/message-templates?propertyId=${propertyId}`);
    if (!res.ok) return;
    const data = await res.json();
    setTemplates((data.templates || []) as MessageTemplate[]);
  };

  useEffect(() => {
    refresh();
  }, [propertyId]);

  const startCreate = () => {
    setEditingId("new");
    setName("");
    setLanguage("en");
    setSubject("");
    setBodyText("");
    setError(null);
  };

  const startEdit = (t: MessageTemplate) => {
    setEditingId(t.id);
    setName(t.name);
    setLanguage(t.language);
    setSubject(t.subject);
    setBodyText(t.body);
    setError(null);
  };

  const cancel = () => {
    setEditingId(null);
    setError(null);
  };

  const save = async () => {
    if (!name.trim() || !bodyText.trim()) {
      setError(c.nameAndBodyRequired);
      return;
    }
    setBusy(true);
    setError(null);
    try {
      const payload = {
        propertyId,
        name: name.trim(),
        language,
        subject,
        body: bodyText,
      };
      if (editingId === "new") {
        const res = await fetch("/api/message-templates", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
        if (!res.ok) {
          const d = await res.json().catch(() => ({}));
          setError(d.error || "Failed");
          return;
        }
      } else if (typeof editingId === "number") {
        const res = await fetch(`/api/message-templates/${editingId}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
        if (!res.ok) {
          const d = await res.json().catch(() => ({}));
          setError(d.error || "Failed");
          return;
        }
      }
      setEditingId(null);
      await refresh();
    } finally {
      setBusy(false);
    }
  };

  const remove = async (id: number) => {
    if (!confirm(c.confirmDelete)) return;
    await fetch(`/api/message-templates/${id}`, { method: "DELETE" });
    await refresh();
  };

  const insertVar = (v: string) => {
    setBodyText((prev) => prev + (prev.endsWith("\n") || prev === "" ? "" : " ") + v);
  };

  return (
    <div className="rounded-lg border border-[var(--line)] bg-[var(--bg-2)] p-4">
      <div className="mb-3 flex items-center justify-between">
        <h3 className="text-sm font-semibold text-[var(--ink)]">
          {c.title}
        </h3>
        {editingId === null && (
          <button
            onClick={startCreate}
            className="rounded-md border border-[var(--line-2)] px-2 py-1 text-xs text-[var(--ink)] hover:bg-[var(--line-2)]"
          >
            {c.newTemplate}
          </button>
        )}
      </div>

      {editingId !== null && (
        <div className="mb-4 space-y-2 rounded-md border border-[var(--line-2)] bg-[var(--bg)] p-3">
          <div className="grid grid-cols-2 gap-2">
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder={c.namePlaceholder}
              className="h-8 rounded-md border border-[var(--line-2)] bg-[var(--bg-2)] px-2 text-xs text-[var(--ink)] outline-none focus:border-[var(--ink)]"
            />
            <select
              value={language}
              onChange={(e) => setLanguage(e.target.value)}
              className="h-8 rounded-md border border-[var(--line-2)] bg-[var(--bg-2)] px-2 text-xs text-[var(--ink)] outline-none focus:border-[var(--ink)]"
            >
              <option value="en">English</option>
              <option value="ru">Русский</option>
            </select>
          </div>
          <input
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder={c.subjectPlaceholder}
            className="h-8 w-full rounded-md border border-[var(--line-2)] bg-[var(--bg-2)] px-2 text-xs text-[var(--ink)] outline-none focus:border-[var(--ink)]"
          />
          <textarea
            value={bodyText}
            onChange={(e) => setBodyText(e.target.value)}
            placeholder={c.bodyPlaceholder}
            rows={5}
            className="w-full rounded-md border border-[var(--line-2)] bg-[var(--bg-2)] px-2 py-1.5 text-xs text-[var(--ink)] outline-none focus:border-[var(--ink)]"
          />
          <div className="flex flex-wrap gap-1.5 text-[11px]">
            <span className="text-[var(--ink-4)]">
              {c.variables}
            </span>
            {VAR_HINTS.map((v) => (
              <button
                key={v}
                onClick={() => insertVar(v)}
                className="rounded bg-[var(--line-2)] px-1.5 py-0.5 font-mono text-[var(--ink-3)] hover:bg-[var(--line-2)] hover:text-[var(--ink)]"
              >
                {v}
              </button>
            ))}
          </div>
          {bodyText && (
            <div className="rounded-md border border-[var(--line)] bg-[var(--bg)] p-2 text-xs">
              <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--ink-4)]">
                {c.preview}
              </div>
              {subject && (
                <div className="mb-1 font-semibold text-[var(--ink)]">
                  {renderTemplate(subject, SAMPLE_VARS)}
                </div>
              )}
              <pre className="whitespace-pre-wrap font-sans text-[var(--ink-2)]">
                {renderTemplate(bodyText, SAMPLE_VARS)}
              </pre>
            </div>
          )}

          {error && <p className="text-xs text-rose-500">{error}</p>}

          <div className="flex justify-end gap-2 pt-1">
            <button
              onClick={cancel}
              disabled={busy}
              className="rounded-md px-2 py-1 text-xs text-[var(--ink-3)] hover:text-[var(--ink)]"
            >
              {c.cancel}
            </button>
            <button
              onClick={save}
              disabled={busy}
              className="rounded-md bg-[var(--m-accent)] px-3 py-1 text-xs font-medium text-white hover:bg-[var(--m-accent-2)] disabled:opacity-50"
            >
              {c.save}
            </button>
          </div>
        </div>
      )}

      {templates.length === 0 ? (
        <p className="text-xs text-[var(--ink-4)]">
          {c.empty}
        </p>
      ) : (
        <ul className="space-y-1.5">
          {templates.map((t) => (
            <li
              key={t.id}
              className="flex items-center justify-between gap-2 rounded-md border border-[var(--line)] bg-[var(--bg)] px-3 py-2 text-xs"
            >
              <div className="min-w-0 flex-1">
                <div className="font-medium text-[var(--ink)]">
                  {t.name}
                  <span className="ml-2 rounded bg-[var(--line-2)] px-1.5 py-0.5 text-[10px] uppercase text-[var(--ink-3)]">
                    {t.language}
                  </span>
                </div>
                <div className="truncate text-[11px] text-[var(--ink-4)]">{t.subject || t.body.slice(0, 80)}</div>
              </div>
              <div className="flex shrink-0 gap-1">
                <button
                  onClick={() => startEdit(t)}
                  className="rounded px-2 py-1 text-[var(--ink-3)] hover:text-[var(--ink)]"
                >
                  {c.edit}
                </button>
                <button
                  onClick={() => remove(t.id)}
                  className="rounded px-2 py-1 text-rose-500 hover:bg-rose-500/10"
                >
                  {c.remove}
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useI18n } from "@/lib/i18n/context";
import { resolveCopy, type Locale, type CopyMap } from "@/lib/i18n/translations";
import { AuditPanel } from "@/components/audit-panel";

interface CopyShape {
  dateLocale: string;
  subtitle: string;
  setPassword: string;
  setPasswordHint: string;
}

const COPY: CopyMap<CopyShape> = {
  en: {
    dateLocale: "en",
    subtitle: "Personal info, password, and activity.",
    setPassword: "Set a password",
    setPasswordHint:
      "You signed in with Google. Set a password to also sign in with your email and password.",
  },
  ru: {
    dateLocale: "ru-RU",
    subtitle: "Личные данные, пароль и активность.",
    setPassword: "Задать пароль",
    setPasswordHint:
      "Вы вошли через Google. Задайте пароль, чтобы также входить по эл. почте и паролю.",
  },
  de: {
    dateLocale: "de-DE",
    subtitle: "Persönliche Daten, Passwort und Aktivität.",
    setPassword: "Passwort festlegen",
    setPasswordHint:
      "Sie haben sich mit Google angemeldet. Legen Sie ein Passwort fest, um sich auch per E-Mail und Passwort anzumelden.",
  },
  fr: {
    dateLocale: "fr-FR",
    subtitle: "Informations personnelles, mot de passe et activité.",
    setPassword: "Définir un mot de passe",
    setPasswordHint:
      "Vous vous êtes connecté avec Google. Définissez un mot de passe pour vous connecter aussi par e-mail et mot de passe.",
  },
  es: {
    dateLocale: "es-ES",
    subtitle: "Datos personales, contraseña y actividad.",
    setPassword: "Establecer una contraseña",
    setPasswordHint:
      "Inició sesión con Google. Establezca una contraseña para iniciar sesión también con su correo y contraseña.",
  },
};

interface ProfileUser {
  id: number;
  username: string;
  role: string;
  createdAt: string;
  hasPassword: boolean;
}

// Renders as a routed dashboard view (no modal overlay) — was a drawer
// but felt like a popup. Lives at activeView === "profile" inside the
// dashboard shell.
export function ProfilePanel() {
  const { t: tr, locale } = useI18n();
  const c = resolveCopy(COPY, locale);
  const [user, setUser] = useState<ProfileUser | null>(null);
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [busy, setBusy] = useState(false);
  const [auditOpen, setAuditOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deletePassword, setDeletePassword] = useState("");
  const [deleteConfirm, setDeleteConfirm] = useState("");
  const [deleteError, setDeleteError] = useState("");
  const [deleteBusy, setDeleteBusy] = useState(false);

  useEffect(() => {
    fetch("/api/auth/me")
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => setUser(data?.user ?? null))
      .catch(() => setUser(null));
  }, []);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError("");
    setSuccess(false);
    try {
      const res = await fetch("/api/auth/change-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ currentPassword, newPassword }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        setError(data.error || "Failed");
        return;
      }
      setSuccess(true);
      setCurrentPassword("");
      setNewPassword("");
    } finally {
      setBusy(false);
    }
  };

  const formatDate = (iso?: string) => {
    if (!iso) return "—";
    return new Date(iso).toLocaleDateString(c.dateLocale, {
      year: "numeric", month: "short", day: "numeric",
    });
  };

  return (
    <div className="mx-auto max-w-2xl space-y-4">
      <div className="rounded-2xl border border-[var(--line)] bg-[var(--bg-2)] p-6 shadow-sm">
        <div className="mb-5">
          <h1 className="text-xl font-semibold text-[var(--ink)]">{tr("profile.title")}</h1>
          <p className="mt-0.5 text-sm text-[var(--ink-3)]">
            {c.subtitle}
          </p>
        </div>

        <dl className="grid grid-cols-2 gap-y-2 text-sm">
          <dt className="text-[var(--ink-4)]">{tr("profile.username")}</dt>
          <dd className="text-[var(--ink)]">{user?.username ?? "…"}</dd>
          <dt className="text-[var(--ink-4)]">{tr("profile.role")}</dt>
          <dd className="text-[var(--ink)]">{user?.role ?? "—"}</dd>
          <dt className="text-[var(--ink-4)]">{tr("profile.createdAt")}</dt>
          <dd className="text-[var(--ink)]">{formatDate(user?.createdAt)}</dd>
        </dl>

        <form onSubmit={submit} className="mt-6 space-y-3 border-t border-[var(--line)] pt-4">
          <h3 className="text-sm font-semibold text-[var(--ink)]">
            {user && !user.hasPassword ? c.setPassword : tr("profile.changePassword")}
          </h3>
          {user && !user.hasPassword && (
            <p className="text-xs text-[var(--ink-3)]">{c.setPasswordHint}</p>
          )}
          {/* Current-password field — shown for accounts that already
              have a real password (and while the profile loads). A
              Google-sign-in account has none, so it's hidden and the
              API sets the first password without it. */}
          {(!user || user.hasPassword) && (
          <div className="space-y-1.5">
            <label className="text-xs text-[var(--ink-3)]" htmlFor="curpw">{tr("profile.currentPassword")}</label>
            <input
              id="curpw"
              type="password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              className="h-9 w-full rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-3 text-sm text-[var(--ink)] outline-none focus:border-[var(--ink)]"
              required
            />
          </div>
          )}
          <div className="space-y-1.5">
            <label className="text-xs text-[var(--ink-3)]" htmlFor="newpw">{tr("profile.newPassword")}</label>
            <input
              id="newpw"
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="h-9 w-full rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-3 text-sm text-[var(--ink)] outline-none focus:border-[var(--ink)]"
              minLength={8}
              required
            />
          </div>

          {error && (
            <div className="rounded-md bg-rose-500/10 border border-rose-500/20 px-3 py-2 text-xs text-rose-500">{error}</div>
          )}
          {success && (
            <div className="rounded-md bg-emerald-500/10 border border-emerald-500/20 px-3 py-2 text-xs text-emerald-500">{tr("profile.saved")}</div>
          )}

          <button
            type="submit"
            disabled={busy}
            className="h-9 w-full rounded-md bg-[var(--m-accent)] text-sm font-medium text-white transition-colors hover:bg-[var(--m-accent-2)] disabled:opacity-50"
          >
            {tr("profile.save")}
          </button>
        </form>

        <button
          type="button"
          onClick={() => setAuditOpen(true)}
          className="mt-4 h-9 w-full rounded-md border border-[var(--line-2)] text-sm text-[var(--ink)] transition-colors hover:bg-[var(--line-2)]"
        >
          Recent activity
        </button>

        <button
          type="button"
          onClick={async () => {
            const res = await fetch("/api/auth/export-data");
            if (!res.ok) return;
            const blob = await res.blob();
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `rent-tool-data-${new Date().toISOString().slice(0, 10)}.json`;
            document.body.appendChild(a);
            a.click();
            a.remove();
            URL.revokeObjectURL(url);
          }}
          className="mt-2 h-9 w-full rounded-md border border-[var(--line-2)] text-sm text-[var(--ink)] transition-colors hover:bg-[var(--line-2)]"
        >
          Download my data
        </button>

        <div className="mt-6 border-t border-[var(--line)] pt-4">
          <h3 className="text-sm font-semibold text-[var(--ink)]">Danger zone</h3>
          <p className="mt-1 text-xs text-[var(--ink-3)]">
            Permanently delete your account and every property, reservation, guest,
            and log we hold. This cannot be undone.
          </p>
          <button
            type="button"
            onClick={() => setDeleteOpen(true)}
            className="mt-3 h-9 w-full rounded-md border border-rose-500/40 text-sm text-rose-500 transition-colors hover:bg-rose-500/10"
          >
            Delete my account
          </button>
        </div>
      </div>

      {deleteOpen && user && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-4">
          <div className="w-full max-w-md rounded-2xl border border-[var(--line)] bg-[var(--bg-2)] p-6 shadow-2xl">
            <h3 className="text-base font-semibold text-[var(--ink)]">Delete account</h3>
            <p className="mt-2 text-sm text-[var(--ink-3)]">
              Type your username <span className="font-mono text-[var(--ink)]">{user.username}</span>{" "}
              and your current password to confirm. We will immediately remove all your
              properties, reservations, guests, calendar links, message templates, cleaning
              records, and audit history. You will be logged out.
            </p>

            <div className="mt-4 space-y-3">
              <div className="space-y-1.5">
                <label className="text-xs text-[var(--ink-3)]" htmlFor="del-confirm">
                  Confirm username
                </label>
                <input
                  id="del-confirm"
                  value={deleteConfirm}
                  onChange={(e) => setDeleteConfirm(e.target.value)}
                  className="h-9 w-full rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-3 text-sm text-[var(--ink)] outline-none focus:border-rose-500"
                  autoComplete="off"
                />
              </div>
              {/* Password proof — skipped for Google-sign-in accounts,
                  which have none; the username confirmation above is
                  the intent check there. */}
              {user.hasPassword && (
                <div className="space-y-1.5">
                  <label className="text-xs text-[var(--ink-3)]" htmlFor="del-pw">
                    Current password
                  </label>
                  <input
                    id="del-pw"
                    type="password"
                    value={deletePassword}
                    onChange={(e) => setDeletePassword(e.target.value)}
                    className="h-9 w-full rounded-md border border-[var(--line-2)] bg-[var(--bg)] px-3 text-sm text-[var(--ink)] outline-none focus:border-rose-500"
                    autoComplete="current-password"
                  />
                </div>
              )}
            </div>

            {deleteError && (
              <div className="mt-3 rounded-md bg-rose-500/10 border border-rose-500/20 px-3 py-2 text-xs text-rose-500">
                {deleteError}
              </div>
            )}

            <div className="mt-5 flex gap-2">
              <button
                type="button"
                onClick={() => setDeleteOpen(false)}
                disabled={deleteBusy}
                className="h-9 flex-1 rounded-md border border-[var(--line-2)] text-sm text-[var(--ink)] transition-colors hover:bg-[var(--line-2)]"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={
                  deleteBusy ||
                  deleteConfirm !== user.username ||
                  (user.hasPassword && deletePassword.length === 0)
                }
                onClick={async () => {
                  setDeleteBusy(true);
                  setDeleteError("");
                  try {
                    const res = await fetch("/api/auth/delete-account", {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({
                        password: deletePassword,
                        confirmUsername: deleteConfirm,
                      }),
                    });
                    if (!res.ok) {
                      const data = await res.json().catch(() => ({}));
                      setDeleteError(data.error || "Failed to delete");
                      return;
                    }
                    window.location.href = "/login";
                  } finally {
                    setDeleteBusy(false);
                  }
                }}
                className="h-9 flex-1 rounded-md bg-rose-500 text-sm font-medium text-white transition-colors hover:bg-rose-600 disabled:opacity-50"
              >
                {deleteBusy ? "Deleting…" : "Permanently delete"}
              </button>
            </div>
          </div>
        </div>
      )}

      <AuditPanel open={auditOpen} onClose={() => setAuditOpen(false)} />
    </div>
  );
}

